import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.address.*; import ghidra.program.model.listing.*;
public class PhysicsOwnerChain extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] a={0x00405320L,0x00405450L,0x00414EF0L,0x004150E0L,0x004193F0L,0x00419400L};for(long x:a){Function f=getFunctionContaining(toAddr(x));println("\n=== "+toAddr(x)+" "+(f==null?"<missing>":f.getName())+" ===");if(f!=null){DecompileResults r=d.decompileFunction(f,150,monitor);if(r.getDecompiledFunction()!=null)println(r.getDecompiledFunction().getC());}}d.dispose();}}
